const QUESTIONS = [{"id": "vb01", "text": "U ziet de Nederlandse vlag. Wat zijn de kleuren van de Nederlandse vlag?", "a": "rood, wit, blauw", "b": "rood, wit, oranje", "correct": "A", "page": 5, "image": "data:image/jpeg;base64,"}, {"id": "vb02", "text": "U ziet een foto. Wie is dit?", "a": "Koningin Maxima", "b": "Willem van Oranje", "correct": "B", "page": 6, "image": "data:image/jpeg;base64,"}, {"id": "1", "text": "In welk deel van de wereld ligt Nederland?", "a": "Europa", "b": "Zuid-Amerika", "correct": "A", "page": 7, "image": "data:image/jpeg;base64,"}, {"id": "2", "text": "Welk land ligt ten zuiden van Nederland?", "a": "België", "b": "Duitsland", "correct": "A", "page": 8, "image": "data:image/jpeg;base64,"}, {"id": "3", "text": "Welk land ligt ten oosten van Nederland?", "a": "België", "b": "Duitsland", "correct": "B", "page": 9, "image": "data:image/jpeg;base64,"}, {"id": "4", "text": "Welk land is groter?", "a": "Marokko", "b": "Nederland", "correct": "A", "page": 10, "image": "data:image/jpeg;base64,"}, {"id": "5", "text": "Welk land is kleiner?", "a": "Nederland", "b": "Turkije", "correct": "A", "page": 11, "image": "data:image/jpeg;base64,"}, {"id": "6", "text": "Wat betekent Nederland?", "a": "laag land", "b": "waterland", "correct": "A", "page": 12, "image": "data:image/jpeg;base64,"}, {"id": "7", "text": "Kijk naar de foto. Wat is dit?", "a": "een dijk", "b": "een haven", "correct": "A", "page": 13, "image": "data:image/jpeg;base64,"}, {"id": "8", "text": "Wat gebeurt er met Nederland als er geen dijken zijn?", "a": "Nederland krijgt meer regen", "b": "Nederland staat onder water", "correct": "B", "page": 14, "image": "data:image/jpeg;base64,"}, {"id": "9", "text": "Welke stad ligt in de Randstad?", "a": "Eindhoven", "b": "Utrecht", "correct": "B", "page": 15, "image": "data:image/jpeg;base64,"}, {"id": "10", "text": "In Nederland, wonen daar veel mensen of weinig mensen?", "a": "veel mensen", "b": "weinig mensen", "correct": "A", "page": 16, "image": "data:image/jpeg;base64,"}, {"id": "11", "text": "Wat is de hoofdstad van Nederland?", "a": "Amsterdam", "b": "Den Haag", "correct": "A", "page": 17, "image": "data:image/jpeg;base64,"}, {"id": "12", "text": "In welke stad zit de regering van Nederland?", "a": "Den Haag", "b": "Rotterdam", "correct": "A", "page": 18, "image": "data:image/jpeg;base64,"}, {"id": "13", "text": "Waar woont de koning van Nederland?", "a": "Groningen", "b": "Zuid-Holland", "correct": "B", "page": 19, "image": "data:image/jpeg;base64,"}, {"id": "14", "text": "Waar ligt de grootste zeehaven van Nederland?", "a": "Amsterdam", "b": "Rotterdam", "correct": "B", "page": 20, "image": "data:image/jpeg;base64,"}, {"id": "15", "text": "Hoe heet de nationale luchthaven van Nederland?", "a": "Europoort", "b": "Schiphol", "correct": "B", "page": 21, "image": "data:image/jpeg;base64,"}, {"id": "16", "text": "Waar ligt Schiphol?", "a": "Amsterdam", "b": "Rotterdam", "correct": "A", "page": 22, "image": "data:image/jpeg;base64,"}, {"id": "17", "text": "Wie helpt u als u in Nederland aankomt?", "a": "de regering", "b": "mijn partner", "correct": "B", "page": 23, "image": "data:image/jpeg;base64,"}, {"id": "18", "text": "Is Nederland vaak droog of nat?", "a": "droog", "b": "nat", "correct": "B", "page": 24, "image": "data:image/jpeg;base64,"}, {"id": "19", "text": "Als u naar Nederland komt, moet u dan opnieuw uw rijbewijs halen?", "a": "ja", "b": "nee", "correct": "A", "page": 25, "image": "data:image/jpeg;base64,"}, {"id": "20", "text": "In Nederland, zijn de wegen daar druk of rustig?", "a": "druk", "b": "rustig", "correct": "A", "page": 26, "image": "data:image/jpeg;base64,"}, {"id": "21", "text": "In Nederland, zijn daar veel fietsen of weinig fietsen?", "a": "veel", "b": "weinig", "correct": "A", "page": 27, "image": "data:image/jpeg;base64,"}, {"id": "22", "text": "Wat is typisch Nederlands in het verkeer?", "a": "boten", "b": "fietsen", "correct": "B", "page": 28, "image": "data:image/jpeg;base64,"}, {"id": "23", "text": "Leven Nederlanders veel binnen of buiten?", "a": "binnen", "b": "buiten", "correct": "A", "page": 29, "image": "data:image/jpeg;base64,"}, {"id": "24", "text": "Wie ziet u op het plaatje?", "a": "de Koning van Spanje", "b": "Willem van Oranje", "correct": "B", "page": 30, "image": "data:image/jpeg;base64,"}, {"id": "25", "text": "Was de koning van Spanje katholiek of protestants?", "a": "katholiek", "b": "protestants", "correct": "A", "page": 31, "image": "data:image/jpeg;base64,"}, {"id": "26", "text": "Hoe lang duurde de oorlog met Spanje?", "a": "8 jaar", "b": "80 jaar", "correct": "B", "page": 32, "image": "data:image/jpeg;base64,"}, {"id": "27", "text": "Hoe lang bestaat de Nederlandse staat ongeveer?", "a": "vijftig jaar", "b": "vierhonderd jaar", "correct": "B", "page": 33, "image": "data:image/jpeg;base64,"}, {"id": "28", "text": "Waren de VOC-schepen voor de handel of voor de visvangst?", "a": "voor de handel", "b": "voor de visvangst", "correct": "A", "page": 34, "image": "data:image/jpeg;base64,"}, {"id": "29", "text": "Wie schilderde dit schilderij?", "a": "Rembrandt van Rijn", "b": "Willem van Oranje", "correct": "A", "page": 35, "image": "data:image/jpeg;base64,"}, {"id": "30", "text": "Is er in Nederland scheiding van kerk en staat?", "a": "ja", "b": "nee", "correct": "A", "page": 36, "image": "data:image/jpeg;base64,"}, {"id": "31", "text": "Door welk land is Nederland bezet tijdens de Tweede Wereldoorlog?", "a": "Duitsland", "b": "Engeland", "correct": "A", "page": 37, "image": "data:image/jpeg;base64,"}, {"id": "32", "text": "Welke grote Nederlandse stad is in 1940 gebombardeerd?", "a": "Amsterdam", "b": "Rotterdam", "correct": "B", "page": 38, "image": "data:image/jpeg;base64,"}, {"id": "33", "text": "Waarom is Anne Frank beroemd?", "a": "Ze schreef een dagboek", "b": "Ze was baas van een museum", "correct": "A", "page": 39, "image": "data:image/jpeg;base64,"}, {"id": "34", "text": "Welke kolonie van Nederland werd onafhankelijk vlak na de Tweede Wereldoorlog?", "a": "Indonesië", "b": "Suriname", "correct": "A", "page": 40, "image": "data:image/jpeg;base64,"}, {"id": "35", "text": "Uit welk land kwamen veel gastarbeiders?", "a": "uit Engeland", "b": "uit Turkije", "correct": "B", "page": 41, "image": "data:image/jpeg;base64,"}, {"id": "36", "text": "Welke kolonie van Nederland werd in 1975 onafhankelijk?", "a": "Nederlandse Antillen", "b": "Suriname", "correct": "B", "page": 42, "image": "data:image/jpeg;base64,"}, {"id": "37", "text": "Wie zijn dit?", "a": "koning Willem-Alexander en koningin Maxima", "b": "prinses Beatrix en haar man Claus", "correct": "A", "page": 43, "image": "data:image/jpeg;base64,"}, {"id": "38", "text": "Uit welk land komt koningin Maxima?", "a": "Argentinië", "b": "Duitsland", "correct": "A", "page": 44, "image": "data:image/jpeg;base64,"}, {"id": "39", "text": "Hoe heet de kroonprinses?", "a": "Amalia", "b": "Beatrix", "correct": "A", "page": 45, "image": "data:image/jpeg;base64,"}, {"id": "40", "text": "Is Nederland een democratie?", "a": "ja", "b": "nee", "correct": "A", "page": 46, "image": "data:image/jpeg;base64,"}, {"id": "41", "text": "In welke stad zit het parlement van Nederland?", "a": "Amsterdam", "b": "Den Haag", "correct": "B", "page": 47, "image": "data:image/jpeg;base64,"}, {"id": "42", "text": "Wat is de belangrijkste wet in Nederland?", "a": "de grondwet", "b": "het parlement", "correct": "A", "page": 48, "image": "data:image/jpeg;base64,"}, {"id": "43", "text": "Wie is de voorzitter van de raad van ministers?", "a": "de koning", "b": "de minister-president", "correct": "B", "page": 49, "image": "data:image/jpeg;base64,"}, {"id": "44", "text": "Wie vergaderen in deze zaal?", "a": "de Eerste Kamer", "b": "de Tweede Kamer", "correct": "B", "page": 50, "image": "data:image/jpeg;base64,"}, {"id": "45", "text": "Hoe vaak zijn er verkiezingen in Nederland?", "a": "elke vier jaar", "b": "elke zes jaar", "correct": "A", "page": 51, "image": "data:image/jpeg;base64,"}, {"id": "46", "text": "Hoe oud moet u zijn om te mogen stemmen in Nederland?", "a": "18 jaar", "b": "21 jaar", "correct": "A", "page": 52, "image": "data:image/jpeg;base64,"}, {"id": "47", "text": "Heeft Nederland één politieke partij of meer politieke partijen?", "a": "één politieke partij", "b": "meer politieke partijen", "correct": "B", "page": 53, "image": "data:image/jpeg;base64,"}, {"id": "48", "text": "Wat is de functie van deze man?", "a": "burgemeester", "b": "minister-president", "correct": "A", "page": 54, "image": "data:image/jpeg;base64,"}, {"id": "49", "text": "Is discriminatie toegestaan in Nederland?", "a": "ja", "b": "nee", "correct": "B", "page": 55, "image": "data:image/jpeg;base64,"}, {"id": "50", "text": "Hebben vrouwen in Nederland méér rechten dan mannen of dezelfde rechten?", "a": "dezelfde rechten als mannen", "b": "meer rechten dan mannen", "correct": "A", "page": 56, "image": "data:image/jpeg;base64,"}, {"id": "51", "text": "Mogen vrouwen in Nederland zelf kiezen met wie ze willen trouwen?", "a": "ja", "b": "nee", "correct": "A", "page": 57, "image": "data:image/jpeg;base64,"}, {"id": "52", "text": "Is het discrimineren van homoseksuelen strafbaar of toegestaan in Nederland?", "a": "strafbaar", "b": "toegestaan", "correct": "A", "page": 58, "image": "data:image/jpeg;base64,"}, {"id": "53", "text": "Heeft Nederland één staatsgodsdienst of zijn er veel godsdiensten?", "a": "Er is één staatsgodsdienst", "b": "Er zijn veel godsdiensten", "correct": "B", "page": 59, "image": "data:image/jpeg;base64,"}, {"id": "54", "text": "Zijn de kranten, radio en televisie vrij in hun mening in Nederland?", "a": "ja", "b": "nee", "correct": "A", "page": 60, "image": "data:image/jpeg;base64,"}, {"id": "55", "text": "Heeft Nederland veel televisiekanalen of is er één staatstelevisie?", "a": "Er is één staatstelevisie", "b": "Er zijn veel televisiekanalen", "correct": "B", "page": 61, "image": "data:image/jpeg;base64,"}, {"id": "56", "text": "Is homoseksualiteit toegestaan of strafbaar in Nederland?", "a": "strafbaar", "b": "toegestaan", "correct": "B", "page": 62, "image": "data:image/jpeg;base64,"}, {"id": "57", "text": "Is wapenbezit zonder vergunning toegestaan of strafbaar in Nederland?", "a": "strafbaar", "b": "toegestaan", "correct": "A", "page": 63, "image": "data:image/jpeg;base64,"}, {"id": "58", "text": "Is vrouwenbesnijdenis toegestaan of strafbaar in Nederland?", "a": "strafbaar", "b": "toegestaan", "correct": "A", "page": 64, "image": "data:image/jpeg;base64,"}, {"id": "59", "text": "Is het slaan van vrouwen toegestaan of strafbaar in Nederland?", "a": "strafbaar", "b": "toegestaan", "correct": "A", "page": 65, "image": "data:image/jpeg;base64,"}, {"id": "60", "text": "Hebben alle mensen in Nederland hetzelfde geloof?", "a": "ja", "b": "nee", "correct": "B", "page": 66, "image": "data:image/jpeg;base64,"}, {"id": "61", "text": "Welke taal spreken de mensen in Nederland?", "a": "Duits", "b": "Nederlands", "correct": "B", "page": 67, "image": "data:image/jpeg;base64,"}, {"id": "62", "text": "Is het belangrijk om snel Nederlands te leren?", "a": "ja", "b": "nee", "correct": "A", "page": 68, "image": "data:image/jpeg;base64,"}, {"id": "63", "text": "Wat leert u in de Nederlandse taalles?", "a": "alle Europese talen", "b": "de Nederlandse taal", "correct": "B", "page": 69, "image": "data:image/jpeg;base64,"}, {"id": "64", "text": "Moet u voor een taalcursus betalen?", "a": "ja", "b": "nee", "correct": "A", "page": 70, "image": "data:image/jpeg;base64,"}, {"id": "65", "text": "Wie betaalt de taalcursus?", "a": "De school betaalt", "b": "Ik betaal zelf", "correct": "B", "page": 71, "image": "data:image/jpeg;base64,"}, {"id": "66", "text": "Gaan in Nederland alleen kinderen naar school of ook volwassenen?", "a": "alleen kinderen", "b": "kinderen en volwassenen", "correct": "B", "page": 72, "image": "data:image/jpeg;base64,"}, {"id": "67", "text": "Worden verjaardagen in Nederland gevierd?", "a": "ja", "b": "nee", "correct": "A", "page": 73, "image": "data:image/jpeg;base64,"}, {"id": "68", "text": "Wat doen Nederlanders meestal als ze bij iemand op bezoek gaan?", "a": "Ze gaan zomaar naar binnen", "b": "Ze maken meestal een afspraak", "correct": "B", "page": 74, "image": "data:image/jpeg;base64,"}, {"id": "69", "text": "Opa's en oma's in Nederland, wonen die bij hun kinderen of wonen ze apart?", "a": "Ze wonen apart", "b": "Ze wonen bij hun kinderen", "correct": "A", "page": 75, "image": "data:image/jpeg;base64,"}, {"id": "70", "text": "Is het voor het leren van de taal goed om met kinderen naar de Nederlandse televisie te kijken?", "a": "ja", "b": "nee", "correct": "A", "page": 76, "image": "data:image/jpeg;base64,"}, {"id": "71", "text": "Wie is in Nederland verantwoordelijk voor wat kinderen doen?", "a": "de ouders", "b": "de school", "correct": "A", "page": 77, "image": "data:image/jpeg;base64,"}, {"id": "72", "text": "Hoe oud zijn de meeste kinderen in Nederland als ze naar school gaan?", "a": "vier jaar", "b": "vijf jaar", "correct": "A", "page": 78, "image": "data:image/jpeg;base64,"}, {"id": "73", "text": "Vanaf welke leeftijd is onderwijs verplicht in Nederland?", "a": "vier jaar", "b": "vijf jaar", "correct": "B", "page": 79, "image": "data:image/jpeg;base64,"}, {"id": "74", "text": "Tot welke leeftijd is onderwijs verplicht in Nederland?", "a": "twaalf jaar", "b": "achttien jaar", "correct": "B", "page": 80, "image": "data:image/jpeg;base64,"}, {"id": "75", "text": "Leren kinderen als ze spelen?", "a": "ja", "b": "nee", "correct": "A", "page": 81, "image": "data:image/jpeg;base64,"}, {"id": "76", "text": "Wie kiest in Nederland de school voor het kind?", "a": "de gemeente", "b": "de ouders", "correct": "B", "page": 82, "image": "data:image/jpeg;base64,"}, {"id": "77", "text": "Zijn er in Nederland op school aparte klassen voor jongens en voor meisjes?", "a": "ja", "b": "nee", "correct": "B", "page": 83, "image": "data:image/jpeg;base64,"}, {"id": "78", "text": "Dragen kinderen in Nederland op school een uniform?", "a": "ja", "b": "nee", "correct": "B", "page": 84, "image": "data:image/jpeg;base64,"}, {"id": "79", "text": "Wat kan deze jongen doen met een computer?", "a": "alleen spelen", "b": "spelen en leren", "correct": "B", "page": 85, "image": "data:image/jpeg;base64,"}, {"id": "80", "text": "Voortgezet onderwijs, is dat voor kinderen vanaf vier jaar of vanaf twaalf jaar?", "a": "vanaf vier jaar", "b": "vanaf twaalf jaar", "correct": "B", "page": 86, "image": "data:image/jpeg;base64,"}, {"id": "81", "text": "Gaan alle kinderen vanaf twaalf jaar naar hetzelfde soort onderwijs, of zijn er twee richtingen?", "a": "Er is één soort", "b": "Er zijn twee richtingen", "correct": "B", "page": 87, "image": "data:image/jpeg;base64,"}, {"id": "82", "text": "Tot welke leeftijd moeten kinderen in Nederland naar school?", "a": "zestien jaar", "b": "achttien jaar", "correct": "B", "page": 88, "image": "data:image/jpeg;base64,"}, {"id": "83", "text": "Vanaf welke leeftijd mogen jongeren hun eigen keuzes maken?", "a": "vanaf zestien jaar", "b": "vanaf achttien jaar", "correct": "B", "page": 89, "image": "data:image/jpeg;base64,"}, {"id": "84", "text": "Is het verplicht om uzelf te verzekeren tegen ziektekosten?", "a": "ja", "b": "nee", "correct": "A", "page": 90, "image": "data:image/jpeg;base64,"}, {"id": "85", "text": "Wie betaalt in Nederland uw verzekering tegen ziektekosten?", "a": "de gemeente", "b": "mijn partner", "correct": "B", "page": 91, "image": "data:image/jpeg;base64,"}, {"id": "86", "text": "Als u ziek wordt, waar kan u in Nederland dan het beste eerst naartoe gaan?", "a": "naar de huisarts", "b": "naar het ziekenhuis", "correct": "A", "page": 92, "image": "data:image/jpeg;base64,"}, {"id": "87", "text": "Waar haalt men in Nederland medicijnen op recept?", "a": "bij de apotheek", "b": "bij de drogist", "correct": "A", "page": 93, "image": "data:image/jpeg;base64,"}, {"id": "88", "text": "Waar gaat u in Nederland in een noodgeval naartoe?", "a": "naar de drogist", "b": "naar het ziekenhuis", "correct": "B", "page": 94, "image": "data:image/jpeg;base64,"}, {"id": "89", "text": "Waar werken de meeste specialisten?", "a": "bij de huisartsenpost", "b": "in het ziekenhuis", "correct": "B", "page": 95, "image": "data:image/jpeg;base64,"}, {"id": "90", "text": "Voor wie is het consultatiebureau?", "a": "voor grote kinderen", "b": "voor kleine kinderen", "correct": "B", "page": 96, "image": "data:image/jpeg;base64,"}, {"id": "91", "text": "Wie werken er in Nederland?", "a": "alleen mannen", "b": "mannen en vrouwen", "correct": "B", "page": 97, "image": "data:image/jpeg;base64,"}, {"id": "92", "text": "Wanneer moet u werk gaan zoeken, zo snel mogelijk of later?", "a": "zo snel mogelijk", "b": "later", "correct": "A", "page": 98, "image": "data:image/jpeg;base64,"}, {"id": "93", "text": "Waar is in Nederland steeds minder werk te vinden?", "a": "in de industrie", "b": "in de zorg", "correct": "A", "page": 99, "image": "data:image/jpeg;base64,"}, {"id": "94", "text": "Waar is in Nederland veel werk te vinden?", "a": "in de landbouw", "b": "in de zorg", "correct": "B", "page": 100, "image": "data:image/jpeg;base64,"}, {"id": "95", "text": "Waar is het in Nederland gemakkelijker om werk te vinden?", "a": "in de beveiliging", "b": "in de landbouw", "correct": "A", "page": 101, "image": "data:image/jpeg;base64,"}, {"id": "96", "text": "Hoe vindt u in Nederland gemakkelijker werk, via de krant of via familie?", "a": "via de krant", "b": "via familie", "correct": "B", "page": 102, "image": "data:image/jpeg;base64,"}, {"id": "97", "text": "Waar kunt u zich in Nederland inschrijven als u werk zoekt?", "a": "bij een school", "b": "bij een uitzendbureau", "correct": "B", "page": 103, "image": "data:image/jpeg;base64,"}, {"id": "98", "text": "Geeft men elkaar in Nederland bij een sollicitatiegesprek eerst een hand of gaat men direct zitten?", "a": "Men gaat direct zitten", "b": "Men geeft elkaar eerst een hand", "correct": "B", "page": 104, "image": "data:image/jpeg;base64,"}, {"id": "99", "text": "Krijgt u in Nederland een uitkering of moet uw partner voor u zorgen?", "a": "Ik krijg een uitkering", "b": "Mijn partner moet voor mij zorgen", "correct": "B", "page": 105, "image": "data:image/jpeg;base64,"}, {"id": "100", "text": "Is het leven in Nederland duur of goedkoop?", "a": "duur", "b": "goedkoop", "correct": "A", "page": 106, "image": "data:image/jpeg;base64,"}];
